#![allow(clippy::excessive_precision)]
//! Golden-parity test for `assign_plates` (JFA Voronoi, PARITY_TESTING.md).
//! Reference HTML lines 2771-2810. Small grids so the golden data stays
//! readable -- same jump-flood algorithm as real map resolution.

use cartalith_terrain::{assign_plates, Plate};

#[test]
fn assign_plates_case_0() {
    let plates = vec![Plate { x: 6.2707394058816135, y: 0.021885769441723824, vx: 0.0, vy: 0.0, base: 0.0 }, Plate { x: 5.274470399599522, y: 7.848407739773393, vx: 0.0, vy: 0.0, base: 0.0 }, Plate { x: 9.68377898214385, y: 2.248828023672104, vx: 0.0, vy: 0.0, base: 0.0 }, Plate { x: 6.1283886060118675, y: 5.765945129096508, vx: 0.0, vy: 0.0, base: 0.0 }, Plate { x: 4.25796952098608, y: 7.958583565428853, vx: 0.0, vy: 0.0, base: 0.0 }];
    let plate_id = assign_plates(10, 8, false, &plates, None, None);
    let expected: Vec<usize> = vec![0, 0, 0, 0, 0, 0, 0, 0, 0, 2, 0, 0, 0, 0, 0, 0, 0, 0, 0, 2, 0, 0, 0, 0, 0, 0, 0, 0, 2, 2, 4, 3, 3, 3, 3, 3, 3, 2, 2, 2, 4, 4, 3, 3, 3, 3, 3, 3, 2, 2, 4, 4, 4, 4, 3, 3, 3, 3, 3, 2, 4, 4, 4, 4, 4, 3, 3, 3, 3, 3, 4, 4, 4, 4, 4, 1, 1, 3, 3, 3];
    assert_eq!(plate_id, expected);
}

